-- Phase 62: restore Co-Marketing reward storage and order reward RPC.
create table if not exists public.parceria_cupons(id uuid primary key default gen_random_uuid(),parceria_id uuid not null references public.parcerias(id) on delete cascade,order_id uuid not null references public.orders(id) on delete cascade,org_origem uuid not null references public.organizations(id) on delete cascade,org_parceira uuid not null references public.organizations(id) on delete cascade,codigo text not null unique,discount_percent numeric not null check(discount_percent between 0 and 100),customer_phone text not null default '',used boolean not null default false,created_at timestamptz not null default now(),unique(order_id));
alter table public.parceria_cupons enable row level security;
revoke all on public.parceria_cupons from anon,authenticated;
create or replace function public.parceria_generate_for_order(_order_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.orders%rowtype; p public.parcerias%rowtype; cid uuid; code text; pname text; pslug text; begin select * into o from public.orders where id=_order_id; if not found then return jsonb_build_object('ok',false,'reason','order_not_found'); end if; if auth.uid() is null then if o.user_id is not null then return jsonb_build_object('ok',false,'reason','unauthenticated_order'); end if; elsif o.user_id is distinct from auth.uid() and not public.usuario_dono_org(o.organization_id,auth.uid()) and not public.eh_super_admin(auth.uid()) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; select * into p from public.parcerias where org_origem=o.organization_id and status='active' and habilitada_origem and habilitada_parceira order by updated_at desc limit 1; if not found then return jsonb_build_object('ok',false,'reason','no_partnership'); end if; if o.total<p.min_order_value then return jsonb_build_object('ok',false,'reason','below_minimum'); end if; select id,codigo into cid,code from public.parceria_cupons where order_id=_order_id; if cid is null then code:='PRC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); insert into public.parceria_cupons(parceria_id,order_id,org_origem,org_parceira,codigo,discount_percent,customer_phone) values(p.id,o.id,p.org_origem,p.org_parceira,code,p.discount_percent,coalesce(o.customer_phone,'')) returning id into cid; end if; select name,slug into pname,pslug from public.organizations where id=p.org_parceira; return jsonb_build_object('ok',true,'codigo',code,'discount_percent',p.discount_percent,'partner_name',pname,'partner_slug',pslug); end$$;
revoke all on function public.parceria_generate_for_order(uuid) from public,authenticated;
grant execute on function public.parceria_generate_for_order(uuid) to anon,authenticated;
